<?php $s=file_get_contents(__DIR__.'/long-catalog.pdf');preg_match_all('/stream\r?\n(.*?)\r?\nendstream/s',$s,$m);$n=0;foreach($m[1] as $r){$n++;$r=trim($r,"\r\n");$d=@gzuncompress($r);if($d===false)$d=@gzinflate($r);if($d!==false&&(strpos($d,'Produk 1')!==false||strpos($d,'Produk 2')!==false)){echo "stream $n ";echo strpos($d,'Produk 1')!==false?'contains Produk 1 ':' ';echo strpos($d,'Produk 2')!==false?'contains Produk 2':'';echo "\n";}}
